<?php namespace App\Http\Controllers;
use App\Models\{Device,SensorReading}; use Illuminate\Http\Request;
class IoTController extends Controller { public function store(Request $r){$d=$r->validate(['device_code'=>'required','soil_moisture'=>'nullable|numeric','temperature'=>'nullable|numeric','humidity'=>'nullable|numeric','ph'=>'nullable|numeric','rainfall'=>'nullable|numeric','water_level'=>'nullable|numeric']);$device=Device::where('device_code',$d['device_code'])->firstOrFail();$reading=SensorReading::create(['device_id'=>$device->id]+collect($d)->except('device_code')->toArray()+['recorded_at'=>now()]);$device->update(['status'=>'online','last_seen'=>now()]);return response()->json(['success'=>true,'data'=>$reading]);} public function index(){return SensorReading::with('device')->latest('recorded_at')->paginate(100);} public function pump(Request $r){$r->validate(['device_code'=>'required','status'=>'required|in:on,off']);$device=Device::where('device_code',$r->device_code)->firstOrFail();return response()->json(['success'=>true,'device'=>$device->device_code,'pump'=>$r->status,'message'=>'Command queued for MQTT integration']);} }
